mapper.select:
SELECT dci.ID FROM dmp_cfg_input AS dci LEFT JOIN dmp_cfg_input_detail AS dcid ON dci.ID = dcid.main_id WHERE dci.is_deleted = 'f' AND dcid.is_deleted = 'f' AND dci.system_id = #{systemId} AND dcid.task_type IN
#{type}
GROUP BY dci.ID

select dci.id AS id, dci.create_time AS createTime, dci.update_time AS updateTime, dci.create_user_name AS createUserName, dci.create_user_id AS createUserId, dci.update_user_name AS updateUserName, dci.update_user_id AS updateUserId, dci.version AS version, dci.is_deleted AS isDeleted, dci.system_id AS systemId, dci.code AS code, dci.name AS name, dci.type AS type, dci.type_id AS typeId, dci.disabled AS disabled, dci.extend_json AS extendJson, dci.exec_system AS execSystem, dci.is_main_task AS isMainTask, dci.bill_type AS billType, dbs.name AS systemName from dmp_cfg_input dci left join dmp_basic_system dbs on dbs.id = dci.system_id where ${params.sqlMap.default} and is_deleted = false
${params.permissionSql}
order by update_time desc

SELECT disabled AS tabFlag, CASE WHEN disabled = FALSE THEN '启用' ELSE '停用' END AS tabFlagName, count(*) AS count FROM dmp_cfg_input WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY disabled
